// Builds the generated parts of the skill: the engine for scripts/build.mjs (scripts/engine.mjs: read, check, the
// workbook, the lesson's recipe) and the map page with its code inside (assets/map.html), from src/ and the pieces of the
// way engine it reuses (the xlsx writer, the drawing kit and contract), pinned by tools/sources.json; and the lesson
// page — chalk-talk's player, from its npm package. Run: npm run assets. Never edit the generated files by hand.
import { build } from 'esbuild'
import { execFileSync } from 'node:child_process'
import { copyFileSync, existsSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { vendor } from 'chalk-talk/kit/tools/vendor.mjs'
const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const repo = resolve(here, '../../..') // the house-lights repository
const skill = join(repo, 'skills/service-blueprint')
const config = join(here, 'sources.json')
if (!existsSync(config)) {
  console.error('✗ tools/sources.json is missing: copy sources.example.json and point it at the way engine.')
  process.exit(1)
}
const lib = resolve(here, JSON.parse(readFileSync(config, 'utf8')).lib)
// the pieces used must be committed, so VERSION says exactly what the skill was built from
const used = ['ways/xlsx.ts', 'ways/workbook.ts', 'drawing']
if (execFileSync('git', ['-C', lib, 'status', '--porcelain', '--', ...used], { encoding: 'utf8' }).trim()) throw new Error(`${lib} has uncommitted changes in ${used.join(', ')}: commit them first.`)
const version = execFileSync('git', ['-C', lib, 'describe', '--tags', '--always'], { encoding: 'utf8' }).trim()
const chalk = JSON.parse(readFileSync(join(repo, 'node_modules/chalk-talk/package.json'), 'utf8')).version
const banner = `// GENERATED by tools/assets.mjs (way engine ${version}). Do not edit.`
// tools/.lib points at the engine, for the typecheck and the checks (tsconfig paths)
rmSync(join(here, '.lib'), { force: true })
symlinkSync(lib, join(here, '.lib'))
// the engine's own files have no side effects: what is not used is left out
const pure = {
  name: 'pure',
  setup(b) {
    b.onResolve({ filter: /^\.\.?\// }, async (a) => {
      if (a.pluginData === 'resolving') return undefined
      const r = await b.resolve(a.path, { resolveDir: a.resolveDir, kind: a.kind, pluginData: 'resolving' })
      return r.errors.length || r.path.includes('node_modules') || !r.path.startsWith(lib) ? r : { ...r, sideEffects: false }
    })
  },
}
const common = { bundle: true, minify: true, write: false, logLevel: 'warning', alias: { '@lib': lib, '@kit': join(repo, 'node_modules/chalk-talk/kit') }, nodePaths: [join(repo, 'node_modules'), join(lib, 'node_modules')], plugins: [pure] }
const engine = await build({ ...common, entryPoints: [join(root, 'src/engine.ts')], format: 'esm', platform: 'node', target: 'node18', banner: { js: "import { createRequire } from 'node:module'; const require = createRequire(import.meta.url);" } })
writeFileSync(join(skill, 'scripts/engine.mjs'), `${banner}\n${engine.outputFiles[0].text}`)

const css = readFileSync(join(root, 'src/page/map.css'), 'utf8')
const page = await build({ ...common, entryPoints: [join(root, 'src/page/map.ts')], format: 'iife', target: 'es2020', define: { __MAP_CSS__: JSON.stringify(css) } })
const script = page.outputFiles[0].text
if (/<\/script/i.test(script)) throw new Error('The map script contains "</script": it would end the page early.')
const html = readFileSync(join(root, 'src/page/template.html'), 'utf8').replace(/\{\{(VERSION|CSS|JS)\}\}/g, (_, k) => ({ VERSION: `engine ${version}`, CSS: css, JS: script })[k])
if (!html.includes('{{BLUEPRINT}}')) throw new Error('The template lost its {{BLUEPRINT}} slot.')
writeFileSync(join(skill, 'assets/map.html'), html)
copyFileSync(join(repo, 'node_modules/chalk-talk/assets/player.html'), join(skill, 'assets/lesson.html'))
// The kit's headless browser (it runs the lesson's reviewer) and page helpers, copied into the skill.
vendor(join(skill, 'scripts'), ['browser.mjs', 'page.mjs'])
writeFileSync(join(skill, 'assets/VERSION'), `engine ${version}\nchalk-talk ${chalk}\n`)
console.log(`✓ assets from the engine ${version} and chalk-talk ${chalk}: engine.mjs ${(engine.outputFiles[0].text.length / 1024).toFixed(0)} KB, map.html ${(html.length / 1024).toFixed(0)} KB`)
